INSERT INTO Course_Section (CRN, course_ID, section_No, faculty_ID, time_Slot_ID, room_ID, semester_ID, max_Seats) SELECT 10921, 'CHEM110', '001', 200061, 1, 'NSC-102', 'SP27', 10 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM Course_Section WHERE CRN = 10921) AND NOT EXISTS (SELECT 1 FROM Course_Section b JOIN Time_Slot_Day d1 ON d1.time_Slot_ID = b.time_Slot_ID JOIN Time_Slot_Day d2 ON d2.time_Slot_ID = 1 AND d2.day_ID = d1.day_ID JOIN Time_Slot_Period q1 ON q1.time_Slot_ID = b.time_Slot_ID JOIN Period p1 ON p1.period_ID = q1.period_ID JOIN Time_Slot_Period q2 ON q2.time_Slot_ID = 1 JOIN Period p2 ON p2.period_ID = q2.period_ID WHERE b.semester_ID = 'SP27' AND (b.room_ID = 'NSC-102' OR b.faculty_ID = 200061) AND p1.start_Time < p2.end_Time AND p2.start_Time < p1.end_Time);
