-- Campus Connect: add 4 departments so there are 10: Chemistry, Physics, History and Economics.
-- Each gets a chair and 3 more full-time professors (with offices), a department office and contact,
-- 8 undergraduate courses with prerequisites, a major and a minor with course requirements, and
-- 5 Spring 2027 sections open for registration (two-day, 80-minute times; free rooms; at most 2 per professor).
-- No existing student, section or schedule is changed. Professors sign in with the demo password Campus123!.
-- Safe to run more than once: rows that already exist are skipped. A Spring 2027 section is skipped if its
-- room or professor is already busy at that time.

USE `campus_connect`;
START TRANSACTION;
















-- Expected: 10 departments, and for each new one 4 professors, 8 courses and 5 Spring 2027 sections.
SELECT d.dept_ID, d.dept_Name, (SELECT COUNT(*) FROM Faculty_Department fd WHERE fd.dept_ID = d.dept_ID) AS faculty,
  (SELECT COUNT(*) FROM Course c WHERE c.dept_ID = d.dept_ID) AS courses,
  (SELECT COUNT(*) FROM Course_Section cs JOIN Course c ON c.course_ID = cs.course_ID WHERE c.dept_ID = d.dept_ID AND cs.semester_ID = 'SP27') AS spring_2027_sections
FROM Department d ORDER BY d.dept_Name;

COMMIT;
